What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int a = 10;
    int *p = &a;
    *p = *p + 5;
    printf("%d", a);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int x = 7 / 2;
    float y = 7 / 2;
    float z = 7 / 2.0f;
    printf("%d %.1f %.1f", x, y, z);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int a = 5;
    int b = a++ + 2;
    int c = ++a * 2;
    printf("%d %d %d", a, b, c);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int arr[] = {10, 20, 30, 40, 50};
    int *p = arr;
    p += 2;
    printf("%d %d %d", *p, *(p - 1), p[2]);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int a = 0, b = 5;
    if (a && ++b)
        printf("X");
    if (a || ++b)
        printf("Y");
    printf("%d", b);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

void update(int x, int *y) {
    x = x * 2;
    *y = *y * 2;
}

int main(void) {
    int a = 3, b = 4;
    update(a, &b);
    printf("%d %d", a, b);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int counter(void) {
    static int c = 0;
    int d = 0;
    c++;
    d++;
    return c * 10 + d;
}

int main(void) {
    counter();
    counter();
    printf("%d", counter());
    return 0;
}
```

