What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    unsigned int u = 1;
    int i = -1;
    if (i < u)
        printf("less");
    else
        printf("not less");
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int x = 5, y = 9;
    int *p = &x;
    int **pp = &p;
    *pp = &y;
    **pp += 1;
    printf("%d %d %d", x, y, *p);
    return 0;
}
```

Consider the following C program. Which single statement can be placed at LINE X without causing undefined behaviour?

```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int *a = malloc(3 * sizeof *a);
    if (a == NULL) return 1;
    int *b = a;
    b[1] = 20;
    free(a);
    a = NULL;
    /* LINE X */
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int n = 13;
    printf("%d %d %d", n & 6, n ^ 6, n >> 1 << 2);
    return 0;
}
```

What is the output of the following C program?

```c
#include <stdio.h>

int main(void) {
    int m[3][4];
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 4; j++)
            m[i][j] = i * 4 + j;
    printf("%d %d %d", *(*(m + 2) + 1), *(m[1] + 3), **m + 1);
    return 0;
}
```

What is the output of the following C program? Assume a 64-bit system where pointers are 8 bytes.

```c
#include <stdio.h>
#include <string.h>

void show(char s[]) {
    printf("%zu %zu ", sizeof(s), strlen(s));
}

int main(void) {
    char msg[16] = "Wipro";
    show(msg);
    printf("%zu %zu", sizeof(msg), strlen(msg));
    return 0;
}
```
